'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
let original='1234',targetHash=OrionProgress.read().hashTarget;
function makeOriginal(){const digits=Array.from({length:3},()=>Math.floor(Math.random()*10));original=digits.join('')+((targetHash-digits.reduce((a,b)=>a+b,0)%10+10)%10);}
if(targetHash!==0)makeOriginal();
function newPuzzle(){targetHash=(targetHash+1+Math.floor(Math.random()*9))%10;OrionProgress.setHashTarget(targetHash);makeOriginal();}
const found=new Set(),openingCodes=new Set();let attempts=[],tries=0,hintLevel=0,state='idle',isOpen=false,rewardSaved=null;
const hash=code=>[...code].reduce((sum,d)=>sum+Number(d),0)%10;
let clearTimer=null;
function cancelCodeClear(){if(clearTimer!==null){clearTimeout(clearTimer);clearTimer=null;}}
function scheduleCodeClear(){cancelCodeClear();clearTimer=setTimeout(()=>{clearTimer=null;$('code').value='';updateMath();},2000);}
const valid=code=>typeof code==='string'&&/^[0-9]{4}$/.test(code);
function updateMath(){const c=$('code').value;$('math').textContent=valid(c)?`${[...c].join(' + ')} = ${[...c].reduce((n,d)=>n+Number(d),0)} → ${t('hash','雜湊值')} ${hash(c)}. ${t(`Stored hash: ${targetHash}.`,`儲存的雜湊值：${targetHash}。`)}`:t('Enter a four-digit code to inspect its hash here.','輸入四位數字，在這裡查看雜湊值。');}
function render(){
$('lesson').innerHTML=t(`<p>The original code for this adventure is <strong>${original}</strong>. The seal adds the digits and keeps the last digit of the total. Its stored hash is <strong>${targetHash}</strong>.</p><p>Try comparing ${original}, 000${targetHash}, and 019${targetHash}. They all produce hash ${targetHash}. Different inputs with the same hash are a <strong>collision</strong>; repeating the same input is not.</p><p>Can Orion find another opening code? Does knowing the hash reveal the original code?</p><p>Reset all sigils on the mission map creates a different target hash. Sealing the gate again keeps the same puzzle so you can explore collisions.</p><p>This deliberately weak teaching hash has only 10 results for 10,000 codes. Real cryptographic hashes make collisions extremely difficult to find. This is not a real security system.</p>`,`<p>這次探險的原本密碼是 <strong>${original}</strong>。封印把四個數字相加，只保留總和的個位數。儲存的雜湊值是 <strong>${targetHash}</strong>。</p><p>試試比較 ${original}、000${targetHash} 和 019${targetHash}，它們的雜湊值都是 ${targetHash}。不同輸入產生相同雜湊值，稱為<strong>碰撞</strong>；重複相同輸入不算碰撞。</p><p>Orion 能找到另一組開門密碼嗎？只知道雜湊值，能找出原本的密碼嗎？</p><p>在任務地圖「重設所有符印」會產生不同的目標雜湊值。「重新封印」則保留同一道謎題，讓你繼續探索碰撞。</p><p>這個刻意簡化的教學雜湊，把 10,000 組密碼對應到只有 10 種結果。真正的密碼學雜湊會讓碰撞極難被找到。這不是真正的保安系統。</p>`);

$('gateState').textContent=isOpen?t('GATE UNSEALED','大門封印已解開'):t('GATE SEALED','大門封印中');$('treasure').hidden=!isOpen;document.body.classList.toggle('open',isOpen);
const messages={idle:t('The seal awaits your code.','封印正等待你的密碼。'),invalid:t('The seal needs exactly four digits, from 0 to 9.','請輸入四位數字，每位數字必須介乎 0 至 9。'),success:t('The seal glows. The treasure is yours!','封印亮起來了。你找到寶藏了！'),failure:t('The stone rumbles… but the gate stays sealed. Try another code.','石門轟隆作響……但封印仍在。試試其他密碼吧。'),relocked:t('The gate is sealed again. Can another code open it?','大門重新封印了。其他密碼也能打開嗎？')};$('status').textContent=messages[state];
$('treasureText').textContent=openingCodes.size>1?t('Another code opens the same gate. What do your successful codes have in common?','另一組密碼也打開了同一道門。這些成功的密碼有甚麼共同之處？'):t('Golden light spills through the doors. Could a different code open them too?','金光從門縫灑出。另一組不同的密碼也能打開它嗎？');
$('sigilStatus').textContent=rewardSaved===false?t('Echo Sigil earned this visit. Browser storage is unavailable, so it cannot be saved.','這次探險已獲得回聲符印，但瀏覽器無法儲存，所以不能保留紀錄。'):OrionProgress.has('echo')?t('Echo Sigil collected!','已收藏回聲符印！'):t('Open the gate to earn the Echo Sigil. Then try finding different opening codes.','打開大門即可獲得回聲符印。然後試試尋找其他開門密碼。');
$('attemptCount').textContent=t(`${tries} ${tries===1?'try':'tries'}`,`${tries} 次嘗試`);$('history').innerHTML=attempts.length?attempts.map(a=>`<li class="${a.open?'success':''}"><code>${a.code}</code><span>${a.open?t('Gate opened','大門已開啟'):t('Sealed','仍然封印')}</span></li>`).join(''):`<li class="empty">${t('Your journey starts here.','你的旅程從這裡開始。')}</li>`;
$('discoveries').textContent=openingCodes.size?t(`${openingCodes.size} different opening ${openingCodes.size===1?'code':'codes'} discovered`,`已找到 ${openingCodes.size} 組不同的開門密碼`):t('No opening codes discovered yet','尚未找到開門密碼');$('collisionCount').textContent=t(`Collisions discovered: ${found.size}`,`已發現的碰撞：${found.size}`);
const clues=[t('Clue 1: The seal adds your four digits together.','提示一：封印會把四個數字相加。'),t('Clue 2: It keeps only the last digit of that total. That short result is called a hash.','提示二：它只保留總和的個位數。這個簡短的結果叫做雜湊值。'),t(`Clue 3: Make a total that ends in ${targetHash}. Different codes can make the same hash!`,`提示三：讓總和的個位數為 ${targetHash}。不同密碼也能產生相同的雜湊值！`)];$('hints').replaceChildren();clues.slice(0,hintLevel).forEach(text=>{const p=document.createElement('p');p.textContent=text;$('hints').append(p)});$('nextHint').hidden=hintLevel===3;$('nextHint').textContent=hintLevel?t('Reveal next clue','揭開下一個提示'):t('Reveal first clue','揭開第一個提示');updateMath();
}
function tryCode(code){scheduleCodeClear();if(!valid(code)){state='invalid';render();return{error:t('Enter exactly four digits.','請輸入四位數字。')};}$('code').value=code;isOpen=hash(code)===targetHash;tries++;if(isOpen)openingCodes.add(code);if(isOpen&&code!==original)found.add(code);attempts=[{code,open:isOpen},...attempts].slice(0,4);if(isOpen)rewardSaved=OrionProgress.earn('echo');state=isOpen?'success':'failure';render();return{code,unlocked:isOpen,uniqueOpeningCodes:openingCodes.size};}
function reset(changeTarget=true){cancelCodeClear();if(changeTarget)newPuzzle();else{targetHash=OrionProgress.read().hashTarget;makeOriginal();}rewardSaved=null;found.clear();openingCodes.clear();attempts=[];tries=0;hintLevel=0;state='idle';isOpen=false;$('code').value='';$('teacher').open=false;if($('secrets').open)$('secrets').close();render();$('code').focus();}
$('form').addEventListener('submit',e=>{e.preventDefault();tryCode($('code').value)});$('code').addEventListener('input',()=>{cancelCodeClear();updateMath();});document.querySelectorAll('[data-digit]').forEach(button=>button.addEventListener('click',()=>{if($('code').value.length<4){cancelCodeClear();$('code').value+=button.dataset.digit;updateMath();}}));$('clear').onclick=()=>{cancelCodeClear();$('code').value='';updateMath();$('code').focus()};$('backspace').onclick=()=>{cancelCodeClear();$('code').value=$('code').value.slice(0,-1);updateMath()};$('relock').onclick=()=>{cancelCodeClear();isOpen=false;state='relocked';$('code').value='';render();$('code').focus()};$('secret').onclick=()=>$('secrets').showModal();$('close').onclick=()=>$('secrets').close();$('nextHint').onclick=()=>{hintLevel=Math.min(3,hintLevel+1);render()};window.addEventListener('orion-language',()=>{if(OrionProgress.read().hashTarget!==targetHash)reset(false);else render();});window.addEventListener('storage',event=>{if(event.key==='orion-expedition-progress-v1'){if(OrionProgress.read().hashTarget!==targetHash)reset(false);else{rewardSaved=null;render();}}});OrionI18n.apply();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'try_hash_passcode',description:'Try a four-digit code at the treasure gate and show whether it opens.',inputSchema:{type:'object',properties:{code:{type:'string',pattern:'^[0-9]{4}$'}},required:['code'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:({code})=>{if(!valid(code))throw new Error(t('Code must contain exactly four digits','密碼必須是四位數字'));return tryCode(code)}})).catch(()=>{});}catch{}}
